using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Animation;
using System.Windows.Threading;
namespace Spectra;
// Device-local secret store. The account ID and endpoint scope prevent account mixing.
public sealed class SocialVault(Store store)
{
 string PathFor(string scope){if(scope.Length!=64||!scope.All(Uri.IsHexDigit))throw new IOException("Неверная область ключей");return Path.Combine(store.Root,"social",scope+".dat");}
 public JsonNode Load(string scope){var path=PathFor(scope);if(!File.Exists(path))return new JsonObject();if(new FileInfo(path).Length>8*1024*1024)throw new IOException("Слишком большое хранилище чата");return JsonNode.Parse(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(path),null,DataProtectionScope.CurrentUser)))??new JsonObject();}
 public void Save(string scope,JsonNode value){var raw=Encoding.UTF8.GetBytes(value.ToJsonString());if(raw.Length>8*1024*1024)throw new IOException("История чатов переполнена");var path=PathFor(scope);Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllBytes(path+".tmp",ProtectedData.Protect(raw,null,DataProtectionScope.CurrentUser));File.Move(path+".tmp",path,true);}
}
public sealed class SocialDesktop:IDisposable
{
 readonly Window main;readonly Action<JsonNode> open;readonly System.Windows.Forms.NotifyIcon tray;readonly MediaPlayer sound=new();readonly Queue<(string Title,string Text,JsonNode Action)> queue=new();Window? popup;bool quitting,disposed;
 public SocialDesktop(Window main,Action<JsonNode> open){this.main=main;this.open=open;var menu=new System.Windows.Forms.ContextMenuStrip();menu.Items.Add("Открыть Spectra",null,(_,_)=>Show());menu.Items.Add("Выйти полностью",null,(_,_)=>{quitting=true;Dispose();Application.Current.Shutdown();});tray=new(){Text="Spectra · работает в фоне",Icon=System.Drawing.Icon.ExtractAssociatedIcon(Environment.ProcessPath!)??System.Drawing.SystemIcons.Application,Visible=true,ContextMenuStrip=menu};tray.DoubleClick+=(_,_)=>Show();main.Closing+=(_,e)=>{if(!quitting){e.Cancel=true;main.Hide();}};Application.Current.SessionEnding+=(_,_)=>quitting=true;}
 public void Show(){main.Show();if(main.WindowState==WindowState.Minimized)main.WindowState=WindowState.Normal;main.Activate();}
 public void Notify(string title,string text,JsonNode action){if(disposed)return;if(queue.Count>=20)queue.Dequeue();queue.Enqueue((title[..Math.Min(title.Length,100)],text[..Math.Min(text.Length,240)],action.DeepClone()));Next();}
 void Next(){if(popup!=null||queue.Count==0||disposed)return;var n=queue.Dequeue();var border=new Border{Background=new SolidColorBrush(Color.FromRgb(21,31,47)),BorderBrush=new SolidColorBrush(Color.FromRgb(104,139,173)),BorderThickness=new Thickness(1),Padding=new Thickness(18),CornerRadius=new CornerRadius(8)};var grid=new Grid();grid.RowDefinitions.Add(new(){Height=GridLength.Auto});grid.RowDefinitions.Add(new(){Height=GridLength.Auto});grid.RowDefinitions.Add(new(){Height=GridLength.Auto});var title=new TextBlock{Text=n.Title,Foreground=Brushes.White,FontSize=15,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,24,8),TextWrapping=TextWrapping.Wrap};var text=new TextBlock{Text=n.Text,Foreground=new SolidColorBrush(Color.FromRgb(184,204,224)),FontSize=12,TextWrapping=TextWrapping.Wrap};Grid.SetRow(text,1);var close=new Button{Content="×",HorizontalAlignment=HorizontalAlignment.Right,Width=24,Height=24};grid.Children.Add(title);grid.Children.Add(text);grid.Children.Add(close);var link=new Button{Content="Открыть в Spectra →",HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,14,0,0),Padding=new Thickness(10,5,10,5)};Grid.SetRow(link,2);grid.Children.Add(link);border.Child=grid;var w=new Window{Width=360,SizeToContent=SizeToContent.Height,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,ShowActivated=false,Topmost=true,AllowsTransparency=true,Background=Brushes.Transparent,Content=border,Opacity=0};popup=w;var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(8)};bool closing=false;void Dismiss(){if(closing)return;closing=true;timer.Stop();if(SystemParameters.ClientAreaAnimation){w.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,TimeSpan.FromMilliseconds(180)));var animation=new DoubleAnimation(w.Left+28,TimeSpan.FromMilliseconds(180));animation.Completed+=(_,_)=>w.Close();w.BeginAnimation(Window.LeftProperty,animation);}else w.Close();}close.Click+=(_,_)=>Dismiss();link.Click+=(_,_)=>{Show();open(n.Action);Dismiss();};border.MouseLeftButtonUp+=(_,e)=>{if(ReferenceEquals(e.OriginalSource,title)||ReferenceEquals(e.OriginalSource,text)){Show();open(n.Action);Dismiss();}};w.Closed+=(_,_)=>{timer.Stop();popup=null;Next();};w.Loaded+=(_,_)=>{var area=SystemParameters.WorkArea;w.Left=area.Right-w.Width-18;w.Top=area.Bottom-w.ActualHeight-18;if(SystemParameters.ClientAreaAnimation){w.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(1,TimeSpan.FromMilliseconds(220)));w.BeginAnimation(Window.LeftProperty,new DoubleAnimation(w.Left+30,w.Left,TimeSpan.FromMilliseconds(220)));}else w.Opacity=1;timer.Start();};timer.Tick+=(_,_)=>Dismiss();w.Show();var path=Path.Combine(AppContext.BaseDirectory,"Web","assets","notification.mp3");try{sound.Open(new Uri(path));sound.Volume=.7;sound.Play();}catch{}}
 public void Clear(){queue.Clear();popup?.Close();sound.Stop();}
 public void Dispose(){if(disposed)return;quitting=true;disposed=true;queue.Clear();popup?.Close();sound.Close();tray.Visible=false;tray.Dispose();}
}
